/**
 * Runtime access to the collection. Everything is bundled at build time from `content/`:
 * no network requests, no gateways, nothing to go down.
 */
import type { Collection, MediaEntry, WorkRecord } from './schema.ts';
import collectionJson from '../../content/collection.json';

const workModules = import.meta.glob<WorkRecord>('../../content/works/*.json', {
  eager: true,
  import: 'default',
});

// Generated by `npm run media`. Optional so a fresh clone without media still renders.
const mediaModules = import.meta.glob<Record<string, MediaEntry>>('../../content/media.json', {
  eager: true,
  import: 'default',
});
const mediaManifest: Record<string, MediaEntry> = Object.values(mediaModules)[0] ?? {};

export interface Work extends WorkRecord {
  media: {
    full: string;
    poster: string;
    thumb: string;
    /** width / height. Falls back to 3:4 (portrait phone photo) when media is missing. */
    aspect: number;
    animated: boolean;
  };
}

function withMedia(record: WorkRecord): Work {
  const entry = mediaManifest[record.slug];
  const base = `/media/works/${record.slug}`;
  // Media filenames are stable, so bust caches with the byte size from media.json (changes on every regen)
  const v = (n: number | undefined) => (n ? `?v=${n.toString(36)}` : '');
  return {
    ...record,
    media: {
      full: `${base}.webp${v(entry?.bytes.full)}`,
      poster: `${base}.poster.webp${v(entry?.bytes.poster)}`,
      thumb: `${base}.thumb.webp${v(entry?.bytes.thumb)}`,
      aspect: entry ? entry.width / entry.height : 3 / 4,
      animated: (entry?.frames ?? 1) > 1,
    },
  };
}

export const works: readonly Work[] = Object.values(workModules)
  .map(withMedia)
  .sort((a, b) => a.id - b.id);

export const collection: Collection = collectionJson;

const bySlug = new Map(works.map((w) => [w.slug, w]));

export function getWork(slug: string | undefined): Work | undefined {
  return slug ? bySlug.get(slug) : undefined;
}

/** Previous / next work in id order, wrapping around. */
export function neighbours(work: Work): { prev: Work; next: Work } {
  const i = works.indexOf(work);
  const n = works.length;
  return { prev: works[(i - 1 + n) % n]!, next: works[(i + 1) % n]! };
}

/** "Srodmiescie" → "Śródmieście". Content keeps ASCII; display gets the real names. */
const DISTRICT_NAMES: Record<string, string> = {
  Srodmiescie: 'Śródmieście',
  Sluzew: 'Służew',
  'Praga Poludnie': 'Praga-Południe',
};

export function districtName(district: string): string {
  return DISTRICT_NAMES[district] ?? district;
}

export function workNumber(work: Pick<Work, 'id'>): string {
  return `#${String(work.id).padStart(2, '0')}`;
}
